# Real-time (online) serving: one request in, one prediction out, fast
class OnlinePredictor:
    def __init__(self, model_artifact):
        self.model = load_model(model_artifact)

    def predict(self, request):
        features = featurize(request)
        return {"prediction": self.model.predict(features)}

# Batch (offline) serving: all known inputs, computed ahead of time
class BatchPredictor:
    def __init__(self, model_artifact):
        self.model = load_model(model_artifact)

    def run_nightly(self, all_known_inputs):
        features = [featurize(r) for r in all_known_inputs]
        predictions = self.model.predict(features)
        write_to_store(predictions)  # ready before anyone asks
